<?php $o=$this->getVar('paymentOperations',array());$csrf=htmlspecialchars($this->getVar('paymentCsrf',''),ENT_QUOTES,'UTF-8');$isAdmin=$this->getVar('paymentIsAdmin',false);?>
<section class="payment-workbench">
<header><p class="eyebrow">PAYMENT OPERATIONS</p><h1>Payments and reconciliation</h1><p>Provider-confirmed state, failed attempts and events are retained without storing card details.</p><?php if($isAdmin):?><p><a class="button" href="<?=$this->uri(array('action'=>'products'))?>">Manage products and prices</a></p><?php endif;?></header>
<article class="payment-card"><h2>Recent checkouts</h2><table><thead><tr><th>Created</th><th>Product</th><th>Amount</th><th>Status</th><th>Reconciliation</th></tr></thead><tbody>
<?php foreach($o['intents']??array() as $i):$pending=in_array($i['state'],array('created','awaiting_approval','processing'),true);?><tr><td><?=htmlspecialchars($i['created_at'])?></td><td><?=htmlspecialchars($i['product_code'])?></td><td><?=htmlspecialchars($i['currency'])?> <?=number_format($i['amount_minor']/100,2)?></td><td><?=htmlspecialchars($i['state'])?></td><td><?php if($pending&&$isAdmin&&$i['provider_code']==='fake'&&$i['state']==='awaiting_approval'&&str_ends_with((string)$i['provider_reference'],':delayed')):?><form method="post" action="<?=$this->uri(array('action'=>'deliverfake'))?>"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><input type="hidden" name="intent_id" value="<?=htmlspecialchars($i['id'])?>"><button class="chisimba-button-secondary" type="submit">Process delayed test event</button></form><?php else:?><?=$pending?'Pending':'Recorded'?><?php endif;?></td></tr><?php endforeach;?></tbody></table></article>
<article class="payment-card"><h2>Verified provider events</h2><table><thead><tr><th>Received</th><th>Event</th><th>Reason</th><th>Processing</th></tr></thead><tbody><?php foreach($o['events']??array() as $e):?><tr><td><?=htmlspecialchars($e['received_at'])?></td><td><?=htmlspecialchars($e['event_type'])?></td><td><?=htmlspecialchars($e['reason_code']??'—')?></td><td><?=htmlspecialchars($e['processing_result']??'Pending')?></td></tr><?php endforeach;?></tbody></table></article>
</section>
